// The question bank is generated by tools/build-bank.mjs from data/questions/*.jsonl.
// Every question is original, AI-written and not yet owner-reviewed, and every option carries its own reason.
import bank from "@/data/bank.json";

export type Track = "deca" | "fbla";

export type Option = { t: string; why: string };

export type Question = {
  id: string;
  track: Track;
  pool: string;
  area: string; // topic
  diff: 1 | 2 | 3;
  q: string;
  options: Option[];
  answer: number;
  exams: string[];
  gen?: boolean; // written live by AI: unreviewed, not saved to the bank, does not count toward rank
};

export const QUESTIONS = bank as Question[];

export function questionsForExam(track: Track, exam: string) {
  return QUESTIONS.filter((q) => q.track === track && q.exams.includes(exam));
}

export function examCount(track: Track, exam: string) {
  return questionsForExam(track, exam).length;
}
